// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/admin/intake/campaigns", wrapper.CreateIntakeCampaign)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/admin/intake/campaigns/{id}/progress", wrapper.GetCampaignProgress)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/cis", wrapper.CreateCI)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/cis/search", wrapper.SearchCIs)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/cis/{id}", wrapper.GetCIDetail)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/cis/{id}/dependencies-downward", wrapper.GetDownwardDependencies)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/cis/{id}/impact-upward", wrapper.GetUpwardImpact)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/edges", wrapper.CreateEdge)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/edges/{id}", wrapper.DeleteEdge)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/edges/{id}/confirm", wrapper.ConfirmEdge)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/edges/{id}/flag-mismatch", wrapper.FlagEdgeMismatch)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/edges/{id}/reject", wrapper.RejectEdge)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/healthz", wrapper.GetHealthz)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/intake/{token}", wrapper.GetIntakeInvitation)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/intake/{token}", wrapper.SaveIntakeDraft)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/intake/{token}/submit", wrapper.SubmitIntake)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/owner-groups", wrapper.ListOwnerGroups)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/owner-groups/pending-edges", wrapper.ListPendingEdges)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/readyz", wrapper.GetReadyz)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/users/me", wrapper.GetCurrentUser)
	})

	return r
}

