// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Create a decentralized intake campaign
	// (POST /api/v1/admin/intake/campaigns)
	CreateIntakeCampaign(ctx context.Context, request CreateIntakeCampaignRequestObject) (CreateIntakeCampaignResponseObject, error)
	// Get intake campaign progress by department
	// (GET /api/v1/admin/intake/campaigns/{id}/progress)
	GetCampaignProgress(ctx context.Context, request GetCampaignProgressRequestObject) (GetCampaignProgressResponseObject, error)
	// Create a single configuration item post-baseline
	// (POST /api/v1/cis)
	CreateCI(ctx context.Context, request CreateCIRequestObject) (CreateCIResponseObject, error)
	// Search configuration items
	// (GET /api/v1/cis/search)
	SearchCIs(ctx context.Context, request SearchCIsRequestObject) (SearchCIsResponseObject, error)
	// Get configuration item detail with graph summary and verification status
	// (GET /api/v1/cis/{id})
	GetCIDetail(ctx context.Context, request GetCIDetailRequestObject) (GetCIDetailResponseObject, error)
	// Traverse downward dependency graph for a configuration item
	// (GET /api/v1/cis/{id}/dependencies-downward)
	GetDownwardDependencies(ctx context.Context, request GetDownwardDependenciesRequestObject) (GetDownwardDependenciesResponseObject, error)
	// Traverse upward impact graph for a configuration item
	// (GET /api/v1/cis/{id}/impact-upward)
	GetUpwardImpact(ctx context.Context, request GetUpwardImpactRequestObject) (GetUpwardImpactResponseObject, error)
	// Create a single edge dependency post-baseline
	// (POST /api/v1/edges)
	CreateEdge(ctx context.Context, request CreateEdgeRequestObject) (CreateEdgeResponseObject, error)
	// Soft-disconnect a graph edge with audit trail
	// (DELETE /api/v1/edges/{id})
	DeleteEdge(ctx context.Context, request DeleteEdgeRequestObject) (DeleteEdgeResponseObject, error)
	// Confirm cross-boundary edge handshake
	// (POST /api/v1/edges/{id}/confirm)
	ConfirmEdge(ctx context.Context, request ConfirmEdgeRequestObject) (ConfirmEdgeResponseObject, error)
	// Flag cross-boundary edge mismatch
	// (POST /api/v1/edges/{id}/flag-mismatch)
	FlagEdgeMismatch(ctx context.Context, request FlagEdgeMismatchRequestObject) (FlagEdgeMismatchResponseObject, error)
	// Reject cross-boundary edge
	// (POST /api/v1/edges/{id}/reject)
	RejectEdge(ctx context.Context, request RejectEdgeRequestObject) (RejectEdgeResponseObject, error)
	// Liveness probe
	// (GET /api/v1/healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// Resolve intake invitation magic link token
	// (GET /api/v1/intake/{token})
	GetIntakeInvitation(ctx context.Context, request GetIntakeInvitationRequestObject) (GetIntakeInvitationResponseObject, error)
	// Auto-save intake draft
	// (PATCH /api/v1/intake/{token})
	SaveIntakeDraft(ctx context.Context, request SaveIntakeDraftRequestObject) (SaveIntakeDraftResponseObject, error)
	// Submit intake and publish baseline
	// (POST /api/v1/intake/{token}/submit)
	SubmitIntake(ctx context.Context, request SubmitIntakeRequestObject) (SubmitIntakeResponseObject, error)
	// List all owner groups
	// (GET /api/v1/owner-groups)
	ListOwnerGroups(ctx context.Context, request ListOwnerGroupsRequestObject) (ListOwnerGroupsResponseObject, error)
	// List pending cross-boundary edges awaiting confirmation
	// (GET /api/v1/owner-groups/pending-edges)
	ListPendingEdges(ctx context.Context, request ListPendingEdgesRequestObject) (ListPendingEdgesResponseObject, error)
	// Readiness probe
	// (GET /api/v1/readyz)
	GetReadyz(ctx context.Context, request GetReadyzRequestObject) (GetReadyzResponseObject, error)
	// Get currently authenticated user profile
	// (GET /api/v1/users/me)
	GetCurrentUser(ctx context.Context, request GetCurrentUserRequestObject) (GetCurrentUserResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

